(5059223, 737993, 98141, '<td valign="top">Would have preferred if the biggest space was in front of where he is looking (having the bird in the upper left rather than the lower left so his gaze was to blue space instead of to the corner of the frame).</td>', 'Would have preferred if the biggest space was in front of where he is looking (having the bird in the upper left rather than the lower left so his gaze was to blue space instead of to the corner of the frame).', '2008-11-12 09:38:38.000000', NULL, 1),
(5059225, 736940, 98141, '<td valign="top">Wish her foot wasn''t cut off, wish she was more in focus, think it would look even cooler if the light was behind her and she was a silhouette or something.</td>', 'Wish her foot wasn''t cut off, wish she was more in focus, think it would look even cooler if the light was behind her and she was a silhouette or something.', '2008-11-12 09:39:30.000000', NULL, 1),
(5059226, 738035, 98141, '<td valign="top">Don''t care much for the composition, wish there was more of the glass and more empty space in the pic.</td>', 'Don''t care much for the composition, wish there was more of the glass and more empty space in the pic.', '2008-11-12 09:40:15.000000', NULL, 1),
(5059228, 738488, 98141, '<td valign="top">Wish the blue was bluer. Pic is a little dull.</td>', 'Wish the blue was bluer. Pic is a little dull.', '2008-11-12 09:41:05.000000', NULL, 1),
(5059231, 736766, 98141, '<td valign="top">Think the light reflections look cool, but there''s nothing technically or creatively amazing about this shot.</td>', 'Think the light reflections look cool, but there''s nothing technically or creatively amazing about this shot.', '2008-11-12 09:41:52.000000', NULL, 1),
