(5059431, 738184, 98141, '<td valign="top">I like this for reasons I can''t really identify. I think the colors are great and they really pop against the black background. Great composition.</td>', 'I like this for reasons I can''t really identify. I think the colors are great and they really pop against the black background. Great composition.', '2008-11-12 10:41:47.000000', NULL, 1),
(5059433, 738669, 98141, '<td valign="top">Beautiful composition and I like the slight overexposure.</td>', 'Beautiful composition and I like the slight overexposure.', '2008-11-12 10:42:06.000000', NULL, 1),
