(5059447, 737889, 98141, '<td valign="top">I think this is another "conversation starter" pic. Nothing great about it, nothing bad about it, but certainly stands out from the crowd.</td>', 'I think this is another "conversation starter" pic. Nothing great about it, nothing bad about it, but certainly stands out from the crowd.', '2008-11-12 10:46:04.000000', NULL, 1),
(5059450, 736890, 98141, '<td valign="top">Good job focusing on a transparent object, seems like a lot of shots in this challenge had trouble doing that.</td>', 'Good job focusing on a transparent object, seems like a lot of shots in this challenge had trouble doing that.', '2008-11-12 10:46:59.000000', NULL, 1),
