(5061985, 738302, 81530, '<td valign="top">Looks like a genuine <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=48228" rel="nofollow" target="_blank">sherpet</a>. Nice colours and variety. 7</td>', 'Looks like a genuine  sherpet. Nice colours and variety. 7', '2008-11-13 12:33:34.000000', NULL, 1),
(5061988, 738482, 81530, '<td valign="top">Yeow! Awesome capture.</td>', 'Yeow! Awesome capture.', '2008-11-13 12:34:31.000000', NULL, 1),
(5062033, 738595, 85384, '<td valign="top">Love the longer exposure and the stepped up blue''s</td>', 'Love the longer exposure and the stepped up blue''s', '2008-11-13 13:13:43.000000', NULL, 1),
(5062036, 737114, 85384, '<td valign="top">The background has creases and i see more green that blue.</td>', 'The background has creases and i see more green that blue.', '2008-11-13 13:14:36.000000', NULL, 1),
(5062040, 738669, 85384, '<td valign="top">Great eyes and good DOF.  Maybe a LITTLE more would have gotten other eye in complete focus.  Very nice</td>', 'Great eyes and good DOF.  Maybe a LITTLE more would have gotten other eye in complete focus.  Very nice', '2008-11-13 13:15:51.000000', NULL, 1);
