(5062421, 737998, 61396, '<td valign="top">Pretty nice impressionistic piece of art! I like the brush strokes, the complementary colors, and the composition. Great job.<br/> <br/>(not voting)</td>', 'Pretty nice impressionistic piece of art! I like the brush strokes, the complementary colors, and the composition. Great job. (not voting)', '2008-11-13 16:26:01.000000', NULL, 1),
