(5063574, 738040, 3087, '<td valign="top">This works well! I like the content, composition and shallow depth of field. I feel it needs a curve adjustment to brighten the highlights, it''s a bit dark all through for me.</td>', 'This works well! I like the content, composition and shallow depth of field. I feel it needs a curve adjustment to brighten the highlights, it''s a bit dark all through for me.', '2008-11-14 12:55:24.000000', NULL, 1),
(5063575, 738411, 3087, '<td valign="top">Lovely textures and details.</td>', 'Lovely textures and details.', '2008-11-14 12:55:42.000000', NULL, 1),
(5063594, 737962, 59276, '<td valign="top">great color and nice &amp; sharp</td>', 'great color and nice & sharp', '2008-11-14 13:13:06.000000', NULL, 1),
(5063595, 738482, 59276, '<td valign="top">I think this one will be wearing a blue!!!</td>', 'I think this one will be wearing a blue!!!', '2008-11-14 13:13:31.000000', NULL, 1),
(5063600, 738120, 59276, '<td valign="top">this one would be great for the Puzzle Macro challenge.... I love it</td>', 'this one would be great for the Puzzle Macro challenge.... I love it', '2008-11-14 13:17:14.000000', NULL, 1),
(5063602, 738136, 59276, '<td valign="top">wonderful shot........I''m sure you will score high</td>', 'wonderful shot........I''m sure you will score high', '2008-11-14 13:18:10.000000', NULL, 1),
(5063611, 738600, 60614, '<td valign="top">Nice crisp focus on the main part of the body.  I can actually see his little hairs on his back.  Intersting prespective.  Looks like he is trying to get away from you.  I really like the muted tones of your backgrond.  The damselfly I took wasn''t near as colorful as this one.  Here is mine [thumb]608371[/thumb]  Pus I couldn''t get as close as you seem to have gotten.  Nicely done.</td>', 'Nice crisp focus on the main part of the body.  I can actually see his little hairs on his back.  Intersting prespective.  Looks like he is trying to get away from you.  I really like the muted tones of your backgrond.  The damselfly I took wasn''t near as colorful as this one.  Here is mine [thumb]608371[/thumb]  Pus I couldn''t get as close as you seem to have gotten.  Nicely done.', '2008-11-14 13:27:35.000000', NULL, 1),
(5063713, 736806, 18655, '<td valign="top">Interesting and artsy. Very nice!</td>', 'Interesting and artsy. Very nice!', '2008-11-14 14:32:07.000000', NULL, 1),
(5063714, 737854, 18655, '<td valign="top">Nice portrait. The blue eyes really stand out. Very good!</td>', 'Nice portrait. The blue eyes really stand out. Very good!', '2008-11-14 14:32:43.000000', NULL, 1),
(5063715, 738025, 18655, '<td valign="top">And a beauty she is. Love the pose for this shot. Great job!</td>', 'And a beauty she is. Love the pose for this shot. Great job!', '2008-11-14 14:33:20.000000', NULL, 1),
(5063717, 738138, 18655, '<td valign="top">Very nice! I like it a lot. The colors are great and good job snapping this towards the sun and able to get both the sun and everything else in a good light. This must be very hard with just one image.</td>', 'Very nice! I like it a lot. The colors are great and good job snapping this towards the sun and able to get both the sun and everything else in a good light. This must be very hard with just one image.', '2008-11-14 14:35:09.000000', NULL, 1),
(5063719, 738124, 18655, '<td valign="top">Not bad. I like the blurred background/bokeh and colors. Good job!</td>', 'Not bad. I like the blurred background/bokeh and colors. Good job!', '2008-11-14 14:36:02.000000', NULL, 1),
(5063721, 737108, 18655, '<td valign="top">You were able to turn this into a very interesting image. Colors are good overall a great photo!</td>', 'You were able to turn this into a very interesting image. Colors are good overall a great photo!', '2008-11-14 14:37:25.000000', NULL, 1),
(5063726, 738373, 18655, '<td valign="top">Great idea and an excellent result!</td>', 'Great idea and an excellent result!', '2008-11-14 14:38:38.000000', NULL, 1),
(5063728, 738298, 18655, '<td valign="top">Great shot! The subjects, the surface and the background - all is just perfect! Without a doubt: 10</td>', 'Great shot! The subjects, the surface and the background - all is just perfect! Without a doubt: 10', '2008-11-14 14:40:46.000000', NULL, 1),
(5063731, 737823, 18655, '<td valign="top">Didn''t I just comment this photo in another challenge? Looks very familiar. But maybe it was just the same location. In any case; great shot!</td>', 'Didn''t I just comment this photo in another challenge? Looks very familiar. But maybe it was just the same location. In any case; great shot!', '2008-11-14 14:42:21.000000', NULL, 1),
(5063737, 738653, 18655, '<td valign="top">Very sharp and pretty to look at but doesn''t tell a story or have values of that kind. I personally prefer other types of photos. But it looks very nice :)</td>', 'Very sharp and pretty to look at but doesn''t tell a story or have values of that kind. I personally prefer other types of photos. But it looks very nice :)', '2008-11-14 14:45:41.000000', NULL, 1),
(5063809, 737998, 67585, '<td valign="top">cool abstract</td>', 'cool abstract', '2008-11-14 15:43:52.000000', NULL, 1),
(5063811, 738618, 62357, '<td valign="top">What a pity you cut off the head in the reflection....</td>', 'What a pity you cut off the head in the reflection....', '2008-11-14 15:44:09.000000', NULL, 1),
(5063818, 738482, 52500, '<td valign="top">Holy crap!  This image made me stop in my tracks.  An insta-10, that''s what that''s called.</td>', 'Holy crap!  This image made me stop in my tracks.  An insta-10, that''s what that''s called.', '2008-11-14 15:48:02.000000', NULL, 1),
(5063830, 738302, 52500, '<td valign="top">Looks good, Shez.</td>', 'Looks good, Shez.', '2008-11-14 15:51:18.000000', NULL, 1),
(5063842, 738600, 54478, '<td valign="top">Great photos. I love the coloration of the dragonfly.</td>', 'Great photos. I love the coloration of the dragonfly.', '2008-11-14 15:54:58.000000', NULL, 1),
(5063843, 738307, 54478, '<td valign="top">Very crisp. I love seeing towers like this lit up in the evening. I really that part of the sunset is used in the background. I know the challenge is "blue", I would really have liked to ahve seen a little more of the pink/red in the photo stand out a bit more.<br/> <br/>Awesome photo!</td>', 'Very crisp. I love seeing towers like this lit up in the evening. I really that part of the sunset is used in the background. I know the challenge is "blue", I would really have liked to ahve seen a little more of the pink/red in the photo stand out a bit more. Awesome photo!', '2008-11-14 15:56:40.000000', NULL, 1),
(5063847, 738494, 54478, '<td valign="top">Very interesting. I like the colors used. Did you use painting with light with a blue laser pen?<br/> <br/>Some of the blue light seems a little over exposed.</td>', 'Very interesting. I like the colors used. Did you use painting with light with a blue laser pen? Some of the blue light seems a little over exposed.', '2008-11-14 15:58:09.000000', NULL, 1),
(5063856, 736940, 54478, '<td valign="top">The bright light on the right takes away from the subject on the left. My eyes want to look at the light and not the dancer. If the light was a little dimmer, if she was a little brighter, or both the photo would have turned out better.<br/> <br/>Still a decent photo for the lighting conditions you were in.</td>', 'The bright light on the right takes away from the subject on the left. My eyes want to look at the light and not the dancer. If the light was a little dimmer, if she was a little brighter, or both the photo would have turned out better. Still a decent photo for the lighting conditions you were in.', '2008-11-14 16:00:41.000000', NULL, 1),
(5063857, 738136, 52500, '<td valign="top">Abstractly delicious.</td>', 'Abstractly delicious.', '2008-11-14 16:00:48.000000', NULL, 1),
(5063861, 738278, 54478, '<td valign="top">Awesome night photo of the city, but I don''t see the color blue.</td>', 'Awesome night photo of the city, but I don''t see the color blue.', '2008-11-14 16:01:43.000000', NULL, 1),
(5063864, 738302, 54478, '<td valign="top">Nice use of different shades of blue and the use of different textures.</td>', 'Nice use of different shades of blue and the use of different textures.', '2008-11-14 16:02:44.000000', NULL, 1),
(5063868, 738207, 54478, '<td valign="top">Beautiful blue sky. Too bad the water was slightly choppy. If the water was smooth... this photo would have been spectacular.</td>', 'Beautiful blue sky. Too bad the water was slightly choppy. If the water was smooth... this photo would have been spectacular.', '2008-11-14 16:03:35.000000', NULL, 1),
(5063872, 737833, 54478, '<td valign="top">I must be dumb because I don''t get it.</td>', 'I must be dumb because I don''t get it.', '2008-11-14 16:04:23.000000', NULL, 1),
(5063875, 737978, 54478, '<td valign="top">Great use of the color blue. The photo is a little grainy, but I am willing to bet that is from a high ISO setting. Would have been great if the photo would have ben ran through a noise reducing filter like "Neat Image" for photoshop.</td>', 'Great use of the color blue. The photo is a little grainy, but I am willing to bet that is from a high ISO setting. Would have been great if the photo would have ben ran through a noise reducing filter like "Neat Image" for photoshop.', '2008-11-14 16:05:38.000000', NULL, 1),
(5063878, 738631, 54478, '<td valign="top">It''s too bad the sun was directly in front of duck, but the flash did a decent job filling in the rest.</td>', 'It''s too bad the sun was directly in front of duck, but the flash did a decent job filling in the rest.', '2008-11-14 16:07:34.000000', NULL, 1),
(5063882, 738298, 54478, '<td valign="top">Very nice. I wish the background was flat white instead of the texture it has.</td>', 'Very nice. I wish the background was flat white instead of the texture it has.', '2008-11-14 16:08:57.000000', NULL, 1),
(5063886, 738658, 54478, '<td valign="top">The photo was taken well, but the subject just isn''t exciting and the background on the man on the right are distracting.</td>', 'The photo was taken well, but the subject just isn''t exciting and the background on the man on the right are distracting.', '2008-11-14 16:09:56.000000', NULL, 1),
(5063889, 738692, 54478, '<td valign="top">Great photo. I love how the color of her fingernails almost match the color of the blue liquid.</td>', 'Great photo. I love how the color of her fingernails almost match the color of the blue liquid.', '2008-11-14 16:11:05.000000', NULL, 1),
(5063890, 738203, 54478, '<td valign="top">Decent try on a long exposure, but the sky just looks too rough.</td>', 'Decent try on a long exposure, but the sky just looks too rough.', '2008-11-14 16:12:07.000000', NULL, 1),
(5063904, 738653, 54478, '<td valign="top">Awesome capture. I like how it appears that the water drop is getting larger as it falls. The only complain is that the background is a tad grainy.</td>', 'Awesome capture. I like how it appears that the water drop is getting larger as it falls. The only complain is that the background is a tad grainy.', '2008-11-14 16:15:34.000000', NULL, 1),
(5063908, 737962, 54478, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2008-11-14 16:17:11.000000', NULL, 1),
(5063909, 738536, 54478, '<td valign="top">The photo feels underexposed.</td>', 'The photo feels underexposed.', '2008-11-14 16:17:39.000000', NULL, 1),
(5063914, 738650, 54478, '<td valign="top">Great macro shot!</td>', 'Great macro shot!', '2008-11-14 16:19:38.000000', NULL, 1),
(5063917, 738563, 54478, '<td valign="top">Creepy.</td>', 'Creepy.', '2008-11-14 16:20:02.000000', NULL, 1),
(5063925, 738509, 54478, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2008-11-14 16:24:39.000000', NULL, 1),
(5063935, 738040, 54478, '<td valign="top">Very creative. I wish the photo was a little brighter.</td>', 'Very creative. I wish the photo was a little brighter.', '2008-11-14 16:28:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5063936, 738641, 69192, '<td valign="top">Very odd choice for a subject, but interesting to look at!  The greens are very vibrant!</td>', 'Very odd choice for a subject, but interesting to look at!  The greens are very vibrant!', '2008-11-14 16:28:24.000000', NULL, 1),
(5063939, 738216, 69192, '<td valign="top">Interesting lines.</td>', 'Interesting lines.', '2008-11-14 16:29:11.000000', NULL, 1),
(5063941, 737885, 54478, '<td valign="top">The lights on the left are distracting.</td>', 'The lights on the left are distracting.', '2008-11-14 16:29:23.000000', NULL, 1),
(5063943, 738002, 69192, '<td valign="top">Shootings stars with your light saber?  Neat idea!</td>', 'Shootings stars with your light saber?  Neat idea!', '2008-11-14 16:29:35.000000', NULL, 1),
(5063951, 738336, 69192, '<td valign="top">The darkness at the top and the bright light on the top of the bottle almost gives me the feeling that this bottle is being interrogated. =)</td>', 'The darkness at the top and the bright light on the top of the bottle almost gives me the feeling that this bottle is being interrogated. =)', '2008-11-14 16:30:20.000000', NULL, 1),
(5063955, 738194, 69192, '<td valign="top">Very nice!  I wish we had pretty birds like that in AZ!  Would be interesting to saturate the blues a little more.</td>', 'Very nice!  I wish we had pretty birds like that in AZ!  Would be interesting to saturate the blues a little more.', '2008-11-14 16:31:22.000000', NULL, 1),
(5063956, 737663, 54478, '<td valign="top">The subject is cropped to close and the lighting from the sunlight behind the Heron, giving it the glow, is a tad distracting. Image also appears out of focus. The only blue I see is on the birds head. If the lighting was different maybe more of the blue/grey hues of the bird would have come out.</td>', 'The subject is cropped to close and the lighting from the sunlight behind the Heron, giving it the glow, is a tad distracting. Image also appears out of focus. The only blue I see is on the birds head. If the lighting was different maybe more of the blue/grey hues of the bird would have come out.', '2008-11-14 16:31:57.000000', NULL, 1),
(5063961, 736883, 69192, '<td valign="top">I''m interested to know how you achieved this effect.  I like the lines created by the light.</td>', 'I''m interested to know how you achieved this effect.  I like the lines created by the light.', '2008-11-14 16:32:59.000000', NULL, 1),
(5063967, 736900, 69192, '<td valign="top">Interesting idea for a subject, but it kind of seems like the focus is a little soft on Cookie Monster, who appears to be the subject.</td>', 'Interesting idea for a subject, but it kind of seems like the focus is a little soft on Cookie Monster, who appears to be the subject.', '2008-11-14 16:34:19.000000', NULL, 1),
(5063969, 738236, 69192, '<td valign="top">Perfect 10!</td>', 'Perfect 10!', '2008-11-14 16:34:53.000000', NULL, 1),
(5063972, 738132, 69192, '<td valign="top">I think the reflection detracts slightly from the image, but this is a great subject for blue.</td>', 'I think the reflection detracts slightly from the image, but this is a great subject for blue.', '2008-11-14 16:35:46.000000', NULL, 1),
(5063976, 738691, 69192, '<td valign="top">The lock seems newer than the rest of the door - would be interesting to see this taken slightly lower so as not to include the lock.  I think there would be a completely different feeling.</td>', 'The lock seems newer than the rest of the door - would be interesting to see this taken slightly lower so as not to include the lock.  I think there would be a completely different feeling.', '2008-11-14 16:37:17.000000', NULL, 1),
(5063981, 737220, 69192, '<td valign="top">Such a vibrant blue color!  Nice framing!</td>', 'Such a vibrant blue color!  Nice framing!', '2008-11-14 16:38:09.000000', NULL, 1),
(5063983, 738427, 69192, '<td valign="top">Because of the shiny texture of the bell, it''s hard to tell which part is in focus.</td>', 'Because of the shiny texture of the bell, it''s hard to tell which part is in focus.', '2008-11-14 16:38:30.000000', NULL, 1),
(5063985, 738121, 69192, '<td valign="top">Is that smoke?</td>', 'Is that smoke?', '2008-11-14 16:39:05.000000', NULL, 1),
(5063987, 738035, 69192, '<td valign="top">I think the texture of the background is a little distracting.  Otherwise, a very nice capture!</td>', 'I think the texture of the background is a little distracting.  Otherwise, a very nice capture!', '2008-11-14 16:39:44.000000', NULL, 1),
(5063991, 737999, 69192, '<td valign="top">This picture has a very calm and wintery feeling to it.  Nice detail work in the front flowers.</td>', 'This picture has a very calm and wintery feeling to it.  Nice detail work in the front flowers.', '2008-11-14 16:41:12.000000', NULL, 1),
(5063996, 738129, 69192, '<td valign="top">This would also be a very effective reflection subject if the angle was closer.  Looks chilly there!</td>', 'This would also be a very effective reflection subject if the angle was closer.  Looks chilly there!', '2008-11-14 16:41:57.000000', NULL, 1),
(5064000, 738278, 69192, '<td valign="top">The blue isn''t completely apparent to me without knowing the subject of the challenge.  Still it''s a very nice, crisp picture!</td>', 'The blue isn''t completely apparent to me without knowing the subject of the challenge.  Still it''s a very nice, crisp picture!', '2008-11-14 16:42:43.000000', NULL, 1),
(5064003, 737966, 69192, '<td valign="top">I like the added colors of the lights behind the bottles.  I would also like this image if it was vertical.</td>', 'I like the added colors of the lights behind the bottles.  I would also like this image if it was vertical.', '2008-11-14 16:44:20.000000', NULL, 1),
(5064008, 738699, 69192, '<td valign="top">So refreshing to see such a different choice for a subject!</td>', 'So refreshing to see such a different choice for a subject!', '2008-11-14 16:45:50.000000', NULL, 1),
(5064013, 738109, 69192, '<td valign="top">The cracks in the flowers and the color seem to emulate some kind of sad emotion.  I love this picture!  It would be awesome to get this picture in all different colors and create some kind of wall collage.  10!</td>', 'The cracks in the flowers and the color seem to emulate some kind of sad emotion.  I love this picture!  It would be awesome to get this picture in all different colors and create some kind of wall collage.  10!', '2008-11-14 16:47:29.000000', NULL, 1),
(5064014, 736991, 69192, '<td valign="top">I like the different shapes this image has.</td>', 'I like the different shapes this image has.', '2008-11-14 16:49:05.000000', NULL, 1),
(5064018, 737993, 69192, '<td valign="top">Beautiful capture of the bird!  Perfect timing!</td>', 'Beautiful capture of the bird!  Perfect timing!', '2008-11-14 16:49:53.000000', NULL, 1),
(5064019, 738669, 69192, '<td valign="top">Adorable blue eyes!  This would also be effective on a pink blanket because her eyes are so blue.</td>', 'Adorable blue eyes!  This would also be effective on a pink blanket because her eyes are so blue.', '2008-11-14 16:50:33.000000', NULL, 1),
(5064024, 738036, 69192, '<td valign="top">Beautiful blue shades!</td>', 'Beautiful blue shades!', '2008-11-14 16:51:12.000000', NULL, 1),
(5064028, 738145, 69192, '<td valign="top">It''s hard to tell if that''s a bird or some kind of kite or plane.  The darkness in the lower right-hand corner is very distracting.</td>', 'It''s hard to tell if that''s a bird or some kind of kite or plane.  The darkness in the lower right-hand corner is very distracting.', '2008-11-14 16:52:00.000000', NULL, 1),
(5064029, 737616, 69192, '<td valign="top">Perfect lighting and dof!  You took a somewhat not interesting subject and made it very interesting!</td>', 'Perfect lighting and dof!  You took a somewhat not interesting subject and made it very interesting!', '2008-11-14 16:52:37.000000', NULL, 1),
(5064032, 738263, 69192, '<td valign="top">Very crisp and clean photo!  Nicely done!</td>', 'Very crisp and clean photo!  Nicely done!', '2008-11-14 16:53:01.000000', NULL, 1),
(5064034, 737823, 69192, '<td valign="top">This place almost seems dreamlike with the trees halfway submerged in the water.  Very beautiful scene!</td>', 'This place almost seems dreamlike with the trees halfway submerged in the water.  Very beautiful scene!', '2008-11-14 16:54:05.000000', NULL, 1),
(5064036, 738618, 69192, '<td valign="top">Awww - poor swan!  I feel this photo would be more effective if you could see the animal''s entire reflection in the water.</td>', 'Awww - poor swan!  I feel this photo would be more effective if you could see the animal''s entire reflection in the water.', '2008-11-14 16:55:14.000000', NULL, 1),
(5064038, 738555, 69192, '<td valign="top">This looks like a postcard; very professional-looking!</td>', 'This looks like a postcard; very professional-looking!', '2008-11-14 16:55:51.000000', NULL, 1),
(5064041, 738067, 69192, '<td valign="top">It seems like the tree is the main subject, not the blue sky reflection.</td>', 'It seems like the tree is the main subject, not the blue sky reflection.', '2008-11-14 16:57:41.000000', NULL, 1),
(5064043, 738482, 69192, '<td valign="top">This is a very neat capture!  The lighting and the foggy-ness add a dreamlike characteristic.</td>', 'This is a very neat capture!  The lighting and the foggy-ness add a dreamlike characteristic.', '2008-11-14 16:58:30.000000', NULL, 1),
(5064045, 738459, 69192, '<td valign="top">I like how the suns rays are just starting to appear in the sky.</td>', 'I like how the suns rays are just starting to appear in the sky.', '2008-11-14 16:59:17.000000', NULL, 1),
(5064046, 738601, 69192, '<td valign="top">Very clear reflection of the entire grouping!  Nicely done!</td>', 'Very clear reflection of the entire grouping!  Nicely done!', '2008-11-14 17:00:23.000000', NULL, 1),
(5064047, 737354, 69192, '<td valign="top">Very crisp!</td>', 'Very crisp!', '2008-11-14 17:00:55.000000', NULL, 1),
(5064049, 736890, 69192, '<td valign="top">A very subdued blue, almost gray.  Interesting shape.</td>', 'A very subdued blue, almost gray.  Interesting shape.', '2008-11-14 17:02:03.000000', NULL, 1),
(5064050, 737833, 69192, '<td valign="top">The bra looks black to me.</td>', 'The bra looks black to me.', '2008-11-14 17:02:32.000000', NULL, 1),
(5064053, 738302, 69192, '<td valign="top">I like the layers of different rocks!  Very nice! 9</td>', 'I like the layers of different rocks!  Very nice! 9', '2008-11-14 17:03:14.000000', NULL, 1),
(5064054, 738040, 69192, '<td valign="top">Cute idea!  Could be a little brighter and maybe have a brownish background to indicate land by the lake.</td>', 'Cute idea!  Could be a little brighter and maybe have a brownish background to indicate land by the lake.', '2008-11-14 17:04:03.000000', NULL, 1),
(5064056, 737895, 69192, '<td valign="top">A deeper depth of field would get rid of the out of focus part in the middle of the face.</td>', 'A deeper depth of field would get rid of the out of focus part in the middle of the face.', '2008-11-14 17:04:55.000000', NULL, 1),
(5064059, 738310, 69192, '<td valign="top">You really could have entered this into either blue or red.  Very interesting shape the flame creates!</td>', 'You really could have entered this into either blue or red.  Very interesting shape the flame creates!', '2008-11-14 17:06:43.000000', NULL, 1),
