(5065250, 738544, 67258, '<td valign="top">This doesn''t quite hit the mark for me.  The composition is a little dull - the pieces of glass neither form a strong pattern, nor are random, and for my tastes their is a little too much negative space to the bottom of the frame.</td>', 'This doesn''t quite hit the mark for me.  The composition is a little dull - the pieces of glass neither form a strong pattern, nor are random, and for my tastes their is a little too much negative space to the bottom of the frame.', '2008-11-15 14:29:31.000000', NULL, 1),
(5065254, 736909, 67258, '<td valign="top">The colour blue is in the composition, but seems to me incidental.  the concept is amoosing, but the implementation hasn''t quite worked - the blue fabric looks too much like a piece of cloth thrown over an armchair; just doesn''t quite work for me.</td>', 'The colour blue is in the composition, but seems to me incidental.  the concept is amoosing, but the implementation hasn''t quite worked - the blue fabric looks too much like a piece of cloth thrown over an armchair; just doesn''t quite work for me.', '2008-11-15 14:32:08.000000', NULL, 1),
