(5065340, 738291, 43774, '<td valign="top">Lovely scene</td>', 'Lovely scene', '2008-11-15 16:06:29.000000', NULL, 1),
(5065342, 738278, 43774, '<td valign="top">Really nice, the blue gives it a cold feeling</td>', 'Really nice, the blue gives it a cold feeling', '2008-11-15 16:07:08.000000', NULL, 1),
(5065344, 738617, 43774, '<td valign="top">A nice night shot and I really like the clouds.</td>', 'A nice night shot and I really like the clouds.', '2008-11-15 16:07:41.000000', NULL, 1),
(5065346, 737823, 43774, '<td valign="top">So still and peaceful looking.</td>', 'So still and peaceful looking.', '2008-11-15 16:07:57.000000', NULL, 1),
(5065347, 737616, 43774, '<td valign="top">A cool blue that makes me think of a warm summer, nice.</td>', 'A cool blue that makes me think of a warm summer, nice.', '2008-11-15 16:08:23.000000', NULL, 1),
(5065349, 738090, 43774, '<td valign="top">That''s really neat.</td>', 'That''s really neat.', '2008-11-15 16:09:03.000000', NULL, 1),
(5065350, 737195, 43774, '<td valign="top">So cool!</td>', 'So cool!', '2008-11-15 16:09:13.000000', NULL, 1),
(5065352, 737859, 43774, '<td valign="top">Great detail in the moon, really nice.</td>', 'Great detail in the moon, really nice.', '2008-11-15 16:09:26.000000', NULL, 1),
(5065354, 738614, 43774, '<td valign="top">Love the look of the water</td>', 'Love the look of the water', '2008-11-15 16:09:40.000000', NULL, 1),
(5065356, 738566, 43774, '<td valign="top">Gorgeous architecture, very good composition.</td>', 'Gorgeous architecture, very good composition.', '2008-11-15 16:09:59.000000', NULL, 1),
(5065357, 738194, 43774, '<td valign="top">Very close! And very nice.</td>', 'Very close! And very nice.', '2008-11-15 16:10:17.000000', NULL, 1),
(5065359, 738665, 43774, '<td valign="top">What a freaky looking bird, so cool and great for this challenge.</td>', 'What a freaky looking bird, so cool and great for this challenge.', '2008-11-15 16:10:39.000000', NULL, 1),
(5065362, 738263, 43774, '<td valign="top">I like the POV, good job.</td>', 'I like the POV, good job.', '2008-11-15 16:11:03.000000', NULL, 1),
(5065363, 737220, 43774, '<td valign="top">Very clear and vibrant, nice.</td>', 'Very clear and vibrant, nice.', '2008-11-15 16:11:13.000000', NULL, 1),
(5065437, 738397, 99351, '<td valign="top">a little too dark. 7</td>', 'a little too dark. 7', '2008-11-15 17:04:57.000000', NULL, 1),
(5065441, 738149, 99351, '<td valign="top">whatever editing you did to this, it was too much.</td>', 'whatever editing you did to this, it was too much.', '2008-11-15 17:06:10.000000', NULL, 1),
(5065446, 737112, 99351, '<td valign="top">hehehe.</td>', 'hehehe.', '2008-11-15 17:07:49.000000', NULL, 1),
(5065466, 738537, 99351, '<td valign="top">blue?</td>', 'blue?', '2008-11-15 17:17:19.000000', NULL, 1),
(5065524, 737999, 51747, '<td valign="top">Don''t see many cornflowers around here. I like the composition. The background is a bit too bright and makes me focus there first. I''d like to see what you can do with advanced editing.</td>', 'Don''t see many cornflowers around here. I like the composition. The background is a bit too bright and makes me focus there first. I''d like to see what you can do with advanced editing.', '2008-11-15 18:28:10.000000', NULL, 1),
(5065609, 737537, 51747, '<td valign="top">I like this image. I think it could be more blue to fit the challenge better.</td>', 'I like this image. I think it could be more blue to fit the challenge better.', '2008-11-15 19:45:32.000000', NULL, 1),
(5065625, 738665, 65234, '<td valign="top">Lovely blue face and QUITE the hairdo.  Well captured.  Looks like he''s staring into space while he desperately tries to remember something ;-)</td>', 'Lovely blue face and QUITE the hairdo.  Well captured.  Looks like he''s staring into space while he desperately tries to remember something ;-)', '2008-11-15 19:55:59.000000', NULL, 1),
(5065627, 737823, 65234, '<td valign="top">It is very calm-loooking, if a rather unusual shade of blue (especially in the clouds).  But the first thing I thought of wasn''t the calm so much as that this looks like a place that has been recently flooded, with those trees sticking out of the water.  The calm after the storm, maybe.</td>', 'It is very calm-loooking, if a rather unusual shade of blue (especially in the clouds).  But the first thing I thought of wasn''t the calm so much as that this looks like a place that has been recently flooded, with those trees sticking out of the water.  The calm after the storm, maybe.', '2008-11-15 19:58:26.000000', NULL, 1),
(5065629, 737962, 65234, '<td valign="top">Great, sharp detail.  Like the DOF you chose and the composition of the bubbles.</td>', 'Great, sharp detail.  Like the DOF you chose and the composition of the bubbles.', '2008-11-15 19:58:58.000000', NULL, 1),
(5065630, 738236, 65234, '<td valign="top">No do-overs on this shot, I guess ;-)  Great capture.</td>', 'No do-overs on this shot, I guess ;-)  Great capture.', '2008-11-15 19:59:03.000000', NULL, 1),
(5065632, 737783, 65234, '<td valign="top">Great composition and lighting and the drop os not only sharp, I can see a swirl of darker color around it''s circumference.  That adds a little something special to this.</td>', 'Great composition and lighting and the drop os not only sharp, I can see a swirl of darker color around it''s circumference.  That adds a little something special to this.', '2008-11-15 20:01:27.000000', NULL, 1),
(5065633, 738184, 65234, '<td valign="top">Jubilant pose is terrific and her wild hair adds to the mania.  Bit of a shadow on her face from her upraised arm, but that makes me think even more strongly that she was in the midst of singing and dancing with wild abandon.</td>', 'Jubilant pose is terrific and her wild hair adds to the mania.  Bit of a shadow on her face from her upraised arm, but that makes me think even more strongly that she was in the midst of singing and dancing with wild abandon.', '2008-11-15 20:04:20.000000', NULL, 1),
(5065637, 738595, 65234, '<td valign="top">The motion in the clouds is really fun.  But it leads my eye to the horizon, which looks tilted to me.  I always have a hard time with shots that are only slightly tilted because I can''t tell if it''s intentional and it makes me cock my head when I look at it.</td>', 'The motion in the clouds is really fun.  But it leads my eye to the horizon, which looks tilted to me.  I always have a hard time with shots that are only slightly tilted because I can''t tell if it''s intentional and it makes me cock my head when I look at it.', '2008-11-15 20:07:22.000000', NULL, 1),
(5065638, 738263, 65234, '<td valign="top">Nice lines.</td>', 'Nice lines.', '2008-11-15 20:07:34.000000', NULL, 1),
(5065639, 737859, 65234, '<td valign="top">Beautiful moon detail.</td>', 'Beautiful moon detail.', '2008-11-15 20:07:55.000000', NULL, 1),
(5065642, 738194, 65234, '<td valign="top">Blue Jays can be pretty entertaining.  This guy looks like he''s trying to peer around a corner without loosening his grip.  Terrific detail on the head and eye.</td>', 'Blue Jays can be pretty entertaining.  This guy looks like he''s trying to peer around a corner without loosening his grip.  Terrific detail on the head and eye.', '2008-11-15 20:09:21.000000', NULL, 1),
(5065645, 737993, 83845, '<td valign="top">Great capture and focus and a nice ''blue''.  Composition would be my only small concern.  I''d like to the ''empty space'' more where the head is pointing... the bird in upper left instead of lower right.  May not have been possible, though.</td>', 'Great capture and focus and a nice ''blue''.  Composition would be my only small concern.  I''d like to the ''empty space'' more where the head is pointing... the bird in upper left instead of lower right.  May not have been possible, though.', '2008-11-15 20:11:03.000000', NULL, 1),
(5065652, 737999, 65234, '<td valign="top">I LOVE cornflowers :-)  One of the few truly blue flowers in nature.  Nice detail and DOF on the flowers.  Would prefer, actually, to see a bit more of them on top instead of bumping into the frame.</td>', 'I LOVE cornflowers :-)  One of the few truly blue flowers in nature.  Nice detail and DOF on the flowers.  Would prefer, actually, to see a bit more of them on top instead of bumping into the frame.', '2008-11-15 20:16:24.000000', NULL, 1),
(5065654, 737978, 65234, '<td valign="top">Ooooh, a luminous jellyfish thingy.  Cool.</td>', 'Ooooh, a luminous jellyfish thingy.  Cool.', '2008-11-15 20:17:07.000000', NULL, 1),
(5065663, 738482, 70000, '<td valign="top">The mood set here is incredible. Beautiful photo</td>', 'The mood set here is incredible. Beautiful photo', '2008-11-15 20:24:04.000000', NULL, 1),
(5065666, 736900, 70000, '<td valign="top">This is a really fun quirky image. I like the composition. I would have liked to see the depth of field blur the background a bit more but i love the dance of forms and the fun atmosphere of the shot</td>', 'This is a really fun quirky image. I like the composition. I would have liked to see the depth of field blur the background a bit more but i love the dance of forms and the fun atmosphere of the shot', '2008-11-15 20:26:35.000000', NULL, 1),
(5065693, 738352, 84384, '<td valign="top">Love this...Beautiful!</td>', 'Love this...Beautiful!', '2008-11-15 21:05:48.000000', NULL, 1);
